-- Spend Wise: MySQL 8.0+ schema
-- Run this file in MySQL Workbench or the MySQL CLI.
-- Currency amounts use DECIMAL, never FLOAT. Store password hashes generated by your backend
-- (Argon2id or bcrypt); never store plaintext passwords.

CREATE DATABASE IF NOT EXISTS spend_wise
  CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE spend_wise;

CREATE TABLE users (
    user_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    full_name VARCHAR(120) NOT NULL,
    email VARCHAR(254) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    email_verified_at DATETIME NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id),
    UNIQUE KEY uq_users_email (email),
    KEY idx_users_active_created (is_active, created_at),
    CONSTRAINT chk_users_full_name CHECK (CHAR_LENGTH(TRIM(full_name)) > 0)
) ENGINE=InnoDB;

CREATE TABLE user_profiles (
    user_id BIGINT UNSIGNED NOT NULL,
    age TINYINT UNSIGNED NULL,
    occupation VARCHAR(120) NULL,
    target_savings DECIMAL(13,2) NOT NULL DEFAULT 0.00,
    financial_bio VARCHAR(500) NULL,
    currency_code CHAR(3) NOT NULL DEFAULT 'INR',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id),
    CONSTRAINT fk_profiles_user FOREIGN KEY (user_id)
        REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT chk_profile_age CHECK (age IS NULL OR age BETWEEN 1 AND 120),
    CONSTRAINT chk_profile_target_savings CHECK (target_savings >= 0),
    CONSTRAINT chk_profile_currency CHECK (currency_code REGEXP '^[A-Z]{3}$')
) ENGINE=InnoDB;

-- One current monthly net-income baseline per user. If you later need historical
-- month-by-month baselines, replace this with a history table keyed by user_id + month.
CREATE TABLE monthly_income_settings (
    user_id BIGINT UNSIGNED NOT NULL,
    net_monthly_income DECIMAL(13,2) NOT NULL DEFAULT 0.00,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id),
    CONSTRAINT fk_income_settings_user FOREIGN KEY (user_id)
        REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT chk_net_monthly_income CHECK (net_monthly_income >= 0)
) ENGINE=InnoDB;

-- User-defined categories/budget allocations shown in Spend Portfolio Manager.
CREATE TABLE spend_portfolio (
    portfolio_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    user_id BIGINT UNSIGNED NOT NULL,
    category_name VARCHAR(80) NOT NULL,
    planned_amount DECIMAL(13,2) NOT NULL DEFAULT 0.00,
    color_hex CHAR(7) NOT NULL DEFAULT '#3A6B4C',
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (portfolio_id),
    UNIQUE KEY uq_portfolio_user_category (user_id, category_name),
    KEY idx_portfolio_user_active_order (user_id, is_active, sort_order),
    CONSTRAINT fk_portfolio_user FOREIGN KEY (user_id)
        REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT chk_portfolio_amount CHECK (planned_amount >= 0),
    CONSTRAINT chk_portfolio_color CHECK (color_hex REGEXP '^#[0-9A-Fa-f]{6}$'),
    CONSTRAINT chk_portfolio_category CHECK (CHAR_LENGTH(TRIM(category_name)) > 0)
) ENGINE=InnoDB;

CREATE TABLE credit_cards (
    credit_card_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    user_id BIGINT UNSIGNED NOT NULL,
    bank_name VARCHAR(100) NOT NULL,
    last_four CHAR(4) NOT NULL,
    holder_name VARCHAR(120) NOT NULL,
    due_day TINYINT UNSIGNED NULL,
    -- Optional actual due date if the UI tracks a specific upcoming payment.
    next_due_date DATE NULL,
    card_nickname VARCHAR(60) NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (credit_card_id),
    KEY idx_cards_user_active (user_id, is_active),
    CONSTRAINT fk_cards_user FOREIGN KEY (user_id)
        REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT chk_card_last_four CHECK (last_four REGEXP '^[0-9]{4}$'),
    CONSTRAINT chk_card_due_day CHECK (due_day IS NULL OR due_day BETWEEN 1 AND 31),
    CONSTRAINT chk_card_bank CHECK (CHAR_LENGTH(TRIM(bank_name)) > 0)
) ENGINE=InnoDB;

CREATE TABLE transactions (
    transaction_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    user_id BIGINT UNSIGNED NOT NULL,
    portfolio_id BIGINT UNSIGNED NULL,
    credit_card_id BIGINT UNSIGNED NULL,
    description VARCHAR(255) NOT NULL,
    amount DECIMAL(13,2) NOT NULL,
    transaction_type ENUM('income', 'expense') NOT NULL,
    transaction_date DATE NOT NULL,
    -- Optional user-entered category label for transactions not mapped to a portfolio.
    category_label VARCHAR(80) NULL,
    notes VARCHAR(500) NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (transaction_id),
    KEY idx_transactions_user_date (user_id, transaction_date DESC, transaction_id DESC),
    KEY idx_transactions_user_type_date (user_id, transaction_type, transaction_date),
    KEY idx_transactions_portfolio_date (portfolio_id, transaction_date),
    KEY idx_transactions_card_date (credit_card_id, transaction_date),
    CONSTRAINT fk_transactions_user FOREIGN KEY (user_id)
        REFERENCES users(user_id) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_transactions_portfolio FOREIGN KEY (portfolio_id)
        REFERENCES spend_portfolio(portfolio_id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT fk_transactions_card FOREIGN KEY (credit_card_id)
        REFERENCES credit_cards(credit_card_id) ON DELETE SET NULL ON UPDATE CASCADE,
    CONSTRAINT chk_transaction_amount CHECK (amount > 0),
    CONSTRAINT chk_transaction_description CHECK (CHAR_LENGTH(TRIM(description)) > 0)
) ENGINE=InnoDB;

